"use strict";
document.addEventListener("DOMContentLoaded", function () {
    var e = document.querySelector(".sidebar__open"),
        t = document.querySelector(".sidebar"),
        o = document.querySelectorAll(".sidebar__link");
    e &&
        t &&
        e.addEventListener("click", function (o) {
            o.preventDefault(), e.classList.toggle("sidebar__open--close"), t.classList.toggle("sidebar--active");
        }),
        o &&
            o.forEach(function (e) {
                e.addEventListener("click", function () {
                    t.classList.contains("sidebar--active") &&
                        (e.parentNode.classList.contains("sidebar__item--dropdown")
                            ? document.querySelectorAll(".sidebar__link").forEach(function (e) {
                                  return e.parentNode.classList.remove("sidebar__item--dropdown");
                              })
                            : (document.querySelectorAll(".sidebar__link").forEach(function (e) {
                                  return e.parentNode.classList.remove("sidebar__item--dropdown");
                              }),
                              e.parentNode.classList.add("sidebar__item--dropdown")));
                });
            });
    var a = document.querySelector(".header-nav__link--user");
    a &&
        a.addEventListener("click", function () {
            //a.parentNode.classList.toggle("header-nav__item--active");
        });
    window.addEventListener("click", function (e) {
        return a && !a.parentNode.contains(e.target) && void a.parentNode.classList.remove("header-nav__item--active");
    });
    var c = document.querySelectorAll(".tabs__item");
    c &&
        c.forEach(function (e, t) {
            e.addEventListener("click", function () {
                document.querySelectorAll(".tabs__item").forEach(function (e) {
                    return e.classList.remove("tabs__item--active");
                }),
                    document.querySelectorAll(".tabs__content").forEach(function (e) {
                        return e.classList.remove("tabs__content--active");
                    }),
                    e.classList.add("tabs__item--active"),
                    document.querySelectorAll(".tabs__content")[t].classList.add("tabs__content--active");
            });
        });
    var n = document.querySelectorAll(".modal-btn"),
        r = document.querySelectorAll(".modal"),
        s = document.querySelectorAll(".modal__close"),
        i = document.querySelector(".modal-overlay");
    n &&
        n.forEach(function (e, t) {
            e.addEventListener("click", function (e) {
                e.preventDefault(), i.classList.contains("modal-overlay--active") || i.classList.add("modal-overlay--active"), document.body.classList.add("scroll-disabled"), r[t].classList.add("modal--active");
            });
        }),
        document.body.addEventListener(
            "keyup",
            function (e) {
                var t = e.keyCode;
                i && r &&
                    i.classList.contains("modal-overlay--active") &&
                    27 == t &&
                    (document.body.classList.remove("scroll-disabled"),
                    document.querySelectorAll(".modal.modal--active").forEach(function (e) {
                        return e.classList.remove("modal--active");
                    }),
                    document.querySelector(".modal-overlay").classList.remove("modal-overlay--active"));
            },
            !1
        ),
        i &&
            i.addEventListener("click", function () {
                r &&
                    i.classList.contains("modal-overlay--active") &&
                    (document.body.classList.remove("scroll-disabled"),
                    document.querySelectorAll(".modal.modal--active").forEach(function (e) {
                        return e.classList.remove("modal--active");
                    }),
                    document.querySelector(".modal-overlay").classList.remove("modal-overlay--active"));
            }),
        s &&
            s.forEach(function (e) {
                e.addEventListener("click", function () {
                    document.body.classList.remove("scroll-disabled"),
                        document.querySelectorAll(".modal.modal--active").forEach(function (e) {
                            return e.classList.remove("modal--active");
                        }),
                        i.classList.remove("modal-overlay--active");
                });
            });
    var l = document.querySelector(".main__more");
    l &&
        l.addEventListener("click", function () {
            var e = document.querySelector(".main__inner--panel");
            e.classList.contains("main__inner--more")
                ? (e.classList.remove("main__inner--more"), l.classList.remove("main__more--reverse"), (l.innerHTML = "Расширенный поиск"))
                : (e.classList.add("main__inner--more"), l.classList.add("main__more--reverse"), (l.innerHTML = "Сжатый поиск"));
        });
    var d = document.getElementById("view-status");
    d &&
        d.addEventListener("click", function () {
            d.checked
                ? (document.querySelector(".list--five.list--orders").classList.remove("list--d-none"), document.querySelector(".list--four.list--orders").classList.add("list--d-none"))
                : (document.querySelector(".list--five.list--orders").classList.add("list--d-none"), document.querySelector(".list--four.list--orders").classList.remove("list--d-none"));
        });
});